Several rigs now have GPS capability

So can add maidenhead output when GPS is available.  This can also be added to output for WSJT-X with a special UDP packet and other consumers via the multicast capability.

#include <stdio.h>
#include <stdlib.h>

#define MAIDENHEAD_LEN 11 // Length including the null terminator

void toMaidenhead(double lat, double lon, char* locator, size_t bufferSize) {
    // Ensure buffer size is sufficient
    if (bufferSize < MAIDENHEAD_LEN) {
        fprintf(stderr, "Error: Buffer size is too small for Maidenhead locator.\n");
        return;
    }

    // Constants for Maidenhead conversion
    const char* letters = "ABCDEFGHIJKLMNOPQRSTUVWX";
    const int lonFieldSize = 20, latFieldSize = 10, lonSquareSize = 2, latSquareSize = 1;
    const double lonSubsquareSize = 5.0 / 60, latSubsquareSize = 2.5 / 60;
    const double lonExtendedSize = 5.0 / 3600, latExtendedSize = 2.5 / 3600;

    // Adjust for negative coordinates
    lon += 180;
    lat += 90;

    // Field
    int lonField = lon / lonFieldSize;
    int latField = lat / latFieldSize;
    locator[0] = letters[lonField];
    locator[1] = letters[latField];

    // Square
    lon -= lonField * lonFieldSize;
    lat -= latField * latFieldSize;
    locator[2] = '0' + (int)(lon / lonSquareSize);
    locator[3] = '0' + (int)(lat / latSquareSize);

    // Subsquare
    lon -= (locator[2] - '0') * lonSquareSize;
    lat -= (locator[3] - '0') * latSquareSize;
    locator[4] = letters[(int)(lon / lonSubsquareSize)];
    locator[5] = letters[(int)(lat / latSubsquareSize)];

    // Extended Subsquare
    lon -= (locator[4] - 'A') * lonSubsquareSize;
    lat -= (locator[5] - 'A') * latSubsquareSize;
    locator[6] = '0' + (int)(lon / lonExtendedSize);
    locator[7] = '0' + (int)(lat / lonExtendedSize);
    lon -= (locator[6] - '0') * lonExtendedSize;
    lat -= (locator[7] - '0') * latExtendedSize;
    locator[8] = '0' + (int)(lon / (lonExtendedSize / 24));
    locator[9] = '0' + (int)(lat / (latExtendedSize / 24));

    locator[10] = '\0'; // Null-terminate the string
}

int main() {
    double latitude, longitude;
    char locator[MAIDENHEAD_LEN];

    printf("Enter latitude: ");
    scanf("%lf", &latitude);
    printf("Enter longitude: ");
    scanf("%lf", &longitude);

    toMaidenhead(latitude, longitude, locator, MAIDENHEAD_LEN);
    printf("Maidenhead Locator: %s\n", locator);

    return 0;
}

