``` c++
// program to demonstrate problem with setting frequency with hamlib on the K3

/*  basic symptom is that *occasionally* the following happens:

    1. call rig_set_freq() to set the frequency;
    2. the call returns RIG_OK [but the rig does not actually change frequency, as can be seen on the physical display]
    3. calling rig_get_freq() responds as if the frequency HAD changed
    4. explicitly requesting the frequency, bypassing hamlib, returns the correct (unchanged) frequency, regardless of whether
         one uses the raw frequency command or the longer "IF" status command
    5. if one keeps reading the frequency using hamlib, without sending any further frequency-change commands,
         then, after one second, hamlib will start to return the correct (unchanged) frequency (the "one second" in this
         item appears to be consistent.


    So the following loops through a sequence of frequency sets (using hamlib), followed by reads using
    both hamlib and the fast and slow explicit commands, and halts on the first occurrence of the behaviour described
    above.

    For simplicity, there is little error checking, and no robust error-handling mechanism in this code.
    However, the code does check the return values from the hamlib frequency-setting and -getting functions.

    The basic flaw seems to be that the frequency-setting function is returning RIG_OK even when it fails to
    set the frequency.

    (There is a question as to why the K3 ever fails to set the frequency correctly... maybe hamlib isn't even sending the command? When
    one uses explicit commands to set the frequency, bypassing hamlib, I don't think I have ever seen a failure.)
*/

#include <array>
#include <iostream>
#include <ranges>
#include <string>
#include <thread>
#include <vector>

#include <cstring>

#include <fcntl.h>
#include <termios.h>
#include <unistd.h>

#include <hamlib/rig.h>

using namespace std;
using namespace std::this_thread;

namespace SR  = std::ranges;
namespace SRV = std::ranges::views;

constexpr size_t FREQ_REPLY_LENGTH   { 14 };          // FA command returns 14 characters
constexpr char   SEMICOLON           { ';' };
constexpr size_t STATUS_REPLY_LENGTH { 38 };          // IF command returns 38 characters

constexpr int BASE_QRG { 28'200'000 };    // base frequency in Hz
constexpr int Δ_QRG    {     10'000 };    // frequency step in Hz
constexpr int N_QRGS   { 10 };            // number of frequencies to test

// forward declarations
optional<string> k3_status             (const int fd);
string           read_fa               (const int fd);
string           read_if               (const int fd);
optional<string> read_until_semicolon  (const int fd);
void             set_blocking          (const int fd, const int should_block);
void             set_interface_attribs (const int fd, const int speed, const int parity);

// global variables
RIG* rigp { nullptr };         // for hamlib access

int main(int argc, char** argv)
{ const int n_loops { (argc == 2) ? stoi(argv[1]) : 100 };

  cout << "n_loops = " << n_loops << endl;

  const string serportname { "/dev/ttyS0"s };

// set up all the hamlib stuff
  constexpr rig_model_t rig_model { RIG_MODEL_K3 };

  rig_set_debug(RIG_DEBUG_NONE);
  rig_load_all_backends();

  if (rigp = rig_init(rig_model), !rigp)
    throw exception();

  rigp -> state.rigport.parm.serial.rate      = 38'400;
  rigp -> state.rigport.parm.serial.data_bits = 8;
  rigp -> state.rigport.parm.serial.stop_bits = 1;

  strncpy(rigp->state.rigport.pathname, serportname.c_str(), FILPATHLEN - 1);

  if (const int status { rig_open(rigp) }; status != RIG_OK)
  { cerr << "unable to open rig with hamlib" << endl;
    throw exception();
  }

// the QRGs through which we are going to loop
  const vector<int> hamlib_f { SR::to<vector>(std::views::iota(0) | std::views::take(N_QRGS) | std::views::transform([] (const auto step) { return (BASE_QRG + step * Δ_QRG); })) };   // hamlib frequencies

  const vector<string> f { SR::to<vector>(hamlib_f | std::views::transform([] (const auto qrg) { return to_string(qrg); })) };   // frequencies as strings

// function to set the hamlib frequency
  auto hamlib_set_f { [] (const int f) { if (const int status { rig_set_freq(rigp, RIG_VFO_A, f) }; status != RIG_OK)
                                           cerr << "hamlib error setting frequency: " << f << endl;                         // note the error, but continue
                                       } };

// function to get the hamlib frequency
  auto hamlib_get_f { [] (void) { freq_t hz;

                                  if (const int status { rig_get_freq(rigp, RIG_VFO_A, &hz) }; status != RIG_OK)
                                    cerr << "hamlib error getting frequency" << endl;                         // note the error, but continue

                                  return static_cast<int>(hz);
                                } };

  const vector<string> f_cmd { SR::to<vector>(f | std::views::transform([] (const string& str) { return "FA"s + string(11 - str.length(), '0') + str + SEMICOLON; })) };  // create the explicit SET commands

  const int fd { open(serportname.c_str(), O_RDWR | O_NOCTTY | O_SYNC) };   // open the port for explicit communication strings

  if (fd < 0)
  { cerr << "unable to open: " << serportname << endl;
    exit(-1);
  }

// set the attributes
  set_interface_attribs (fd, B38400, 0);
  set_blocking (fd, 0);                     // set no blocking

  for (int loop_nr { 0 }; loop_nr < n_loops; ++loop_nr)
  { cout << "EXPLICIT COMMANDS" << endl;

    for (int idx { 0 }; idx < 10; ++idx)
    { const string& set_f { f_cmd[idx] };

      write (fd, set_f.c_str(), set_f.size());   // send the explicit command to change frequency

      const string fast_read_str { read_fa(fd) };
      const string slow_read_str { read_if(fd) };

      if (fast_read_str != slow_read_str)
      { cerr << "mismatch" << endl;
        exit(0);
      }
    }

    cout << "HAMLIB COMMANDS" << endl;

    for (int idx { 0 }; idx < 10; ++idx)
    { const int set_f { hamlib_f[idx] };

      hamlib_set_f(set_f);

      const int read_f { hamlib_get_f() };

      cout << "hamlib read frequency = " << read_f << endl;

      const string fast_read_str { read_fa(fd) };
      const string slow_read_str { read_if(fd) };

      if ( (read_f != stoi(slow_read_str)) or (fast_read_str != slow_read_str) )
      { cerr << "mismatch" << endl;

        for (int n { 0 }; n < 20; ++n)       // loop for 2s. without changing the frequency
        { const int read_f { hamlib_get_f() };

          cout << " hamlib retry after " << 100 * n << "ms : hamlib read frequency = " << read_f << endl;
          sleep_for(100ms);
        }

        exit(0);
      }
    }

  }

  return 0;
}

// read frequency using the explicit FA command
string read_fa(const int fd)
{ string rv             { };
  optional<string> sbuf { };

  while (!sbuf)
  { write (fd, "FA;", 3); // request frequency

    sbuf = read_until_semicolon(fd);

    if (sbuf and (sbuf.value().size() == FREQ_REPLY_LENGTH))
    { rv = sbuf.value().substr(2, 11);

      cout << "fast read string = " << rv << endl;
    }
    else
    { char buf [100];

      sleep_for(100ms);
      read(fd, buf, sizeof buf);    // this should clear any buffers so we can try again
    }
  }

  return rv;
}

// read frequency using the explicit IF command
string read_if(const int fd)
{ string rv { };

  const optional<string> sbuf2 { k3_status(fd) };

  if (sbuf2)
  { rv = sbuf2.value().substr(2, 11);

    cout << "slow read string = " << rv << endl;
  }

  return rv;
}

// read from the rig until a semicolon is read
optional<string> read_until_semicolon(const int fd)
{ char buf [100];

  optional<string> rv      { };
  int              counter { 0 };

  while ((!rv or !rv.value().contains(SEMICOLON)) and (counter++ < 10 ))
  { const int n_read { static_cast<int>(read (fd, buf, sizeof buf)) };

    if (rv)
      rv = rv.value() + string(buf, n_read);
    else
      rv = string(buf, n_read);

    if (!rv.value().contains(SEMICOLON))
      sleep_for(10ms);
  }

  if (rv and !rv.value().contains(SEMICOLON))   // first test should always be true
    rv.reset();

  return rv;
}

// obtain the response to an IF command
optional<string> k3_status(const int fd)
{ int              returned_length { 0 };
  optional<string> rv              { };

  while (returned_length != STATUS_REPLY_LENGTH)   // sometimes the K3 does not respond with the correct length
  { write (fd, "IF;", 3);

    rv = read_until_semicolon(fd);

    if (rv)
    { returned_length = rv.value().size();

      if (returned_length != STATUS_REPLY_LENGTH)
      { sleep_for(100ms);

        char buf [100];

        read (fd, buf, sizeof buf);
      }
    }
  }

  return rv;
}

// taken from: https://stackoverflow.com/questions/6947413/how-to-open-read-and-write-from-serial-port-in-c
void set_interface_attribs (const int fd, const int speed, const int parity)
{ struct termios tty { };

  if (tcgetattr (fd, &tty) != 0)
  { cerr << "error " << errno << " from tcgetattr in set_interface_attribs()" << endl;
    exit(-1);
  }

  cfsetospeed (&tty, speed);
  cfsetispeed (&tty, speed);

  tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
  // disable IGNBRK for mismatched speed tests; otherwise receive break
  // as \000 chars
  tty.c_iflag &= ~IGNBRK;         // disable break processing
  tty.c_lflag = 0;                // no signaling chars, no echo,
                                        // no canonical processing
  tty.c_oflag = 0;                // no remapping, no delays
  tty.c_cc[VMIN]  = 0;            // read doesn't block
  tty.c_cc[VTIME] = 5;            // 0.5 seconds read timeout

  tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

  tty.c_cflag |= (CLOCAL | CREAD);// ignore modem controls,
                                        // enable reading
  tty.c_cflag &= ~(PARENB | PARODD);      // shut off parity
  tty.c_cflag |= parity;
  tty.c_cflag &= ~CSTOPB;
  tty.c_cflag &= ~CRTSCTS;

  if (tcsetattr (fd, TCSANOW, &tty) != 0)
  { cerr << "error " << errno << " from tcsetattr in set_interface_attribs()" << endl;
    exit(-1);
  }
}

// taken from: https://stackoverflow.com/questions/6947413/how-to-open-read-and-write-from-serial-port-in-c
void set_blocking (const int fd, const int should_block)
{ struct termios tty;

  memset (&tty, 0, sizeof tty);

  if (tcgetattr (fd, &tty) != 0)
  { cerr << "error " << errno << " from tcgetattr in set_blocking()" << endl;
    exit(-1);
  }

  tty.c_cc[VMIN]  = (should_block ? 1 : 0);
  tty.c_cc[VTIME] = 5;            // 0.5 seconds read timeout

  if (tcsetattr (fd, TCSANOW, &tty) != 0)
  { cerr << "error " << errno << " setting term attributes" << endl;
    exit(-1);
  }
}

